prompt --application/shared_components/plugins/region_type/apex_qr_scanner
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(41912811251073412)
,p_plugin_type=>'REGION TYPE'
,p_name=>'APEX_QR_SCANNER'
,p_display_name=>'APEX QR Scanner'
,p_apexlang_name=>'apexQrScanner'
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'procedure render_region (',
'    p_plugin in            apex_plugin.t_plugin,',
'    p_region in            apex_plugin.t_region,',
'    p_param  in            apex_plugin.t_region_render_param,',
'    p_result in out nocopy apex_plugin.t_region_render_result )',
'is',
'    l_target_item  varchar2(255) := p_region.attributes.get_varchar2(''target-item'');',
'    l_facing       varchar2(20)  := nvl(p_region.attributes.get_varchar2(''camera-facing''), ''environment'');',
'    l_stop         varchar2(5)   := case when upper(nvl(p_region.attributes.get_varchar2(''stop-after-scan''), ''Y'')) in (''Y'',''TRUE'')',
'                                         then ''Y'' else ''N'' end;',
'    l_region_id    varchar2(255) := p_region.static_id;',
'    l_root_id      varchar2(300) := p_region.static_id || ''_aqr'';',
'    l_options      varchar2(4000);',
'begin',
'    if p_param.is_printer_friendly then',
'        return;',
'    end if;',
'',
'    if l_target_item is null then',
'        raise_application_error(-20001, ''APEX QR Scanner: Target page item is required.'');',
'    end if;',
'',
'    if l_facing not in (''environment'', ''user'') then',
'        l_facing := ''environment'';',
'    end if;',
'',
'    apex_javascript.add_library(',
'        p_name           => ''js/jsQR'',',
'        p_directory      => p_plugin.file_prefix,',
'        p_version        => null,',
'        p_skip_extension => false );',
'',
'    apex_javascript.add_library(',
'        p_name           => ''js/qr-scanner'',',
'        p_directory      => p_plugin.file_prefix,',
'        p_version        => null,',
'        p_skip_extension => false );',
'',
'    apex_css.add_file(',
'        p_name      => ''css/qr-scanner'',',
'        p_directory => p_plugin.file_prefix,',
'        p_version   => null );',
'',
'    sys.htp.p(''<div id="'' || apex_escape.html_attribute(l_root_id) || ''" class="aqr">'');',
'    sys.htp.p(''<div class="aqr-camera">''',
'        || ''<video class="aqr-video" autoplay muted playsinline></video>''',
'        || ''<div class="aqr-overlay"><div class="aqr-frame"></div></div>''',
'        || ''</div>'');',
'    sys.htp.p(''<div class="aqr-status" role="status" aria-live="polite">Ready to scan</div>'');',
'    sys.htp.p(''<div class="aqr-error" role="alert" hidden></div>'');',
'    sys.htp.p(''<div class="aqr-controls">''',
'        || ''<button type="button" class="aqr-start">Start Camera</button>''',
'        || ''<button type="button" class="aqr-stop" hidden>Stop Camera</button>''',
'        || ''<button type="button" class="aqr-switch">Switch Camera</button>''',
'        || ''</div>'');',
'    sys.htp.p(''</div>'');',
'',
'    l_options :=',
'        ''{"targetItem":''    || apex_escape.js_literal(l_target_item) ||',
'        '',"facingMode":''    || apex_escape.js_literal(l_facing) ||',
'        '',"stopAfterScan":'' || case when l_stop = ''Y'' then ''true'' else ''false'' end ||',
'        '',"regionId":''      || apex_escape.js_literal(l_region_id) || ''}'';',
'',
'    apex_javascript.add_onload_code(',
'        p_code => ''APEXQRScanner.init('' || apex_escape.js_literal(l_root_id) || '','' || l_options || '');'' );',
'end render_region;'))
,p_partial_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div id="#APEX$DOM_ID#">#MY_FIRST_PLACEHOLDER#</div>',
'{if MY_SECOND_PLACEHOLDER/}<div>#MY_SECOND_PLACEHOLDER#</div>{endif/}',
''))
,p_api_version=>3
,p_render_function=>'render_region'
,p_version_scn=>'SH256:d1tXXJjZk6cDOkhOjpzf1oTJyKpkZhwHiysLhwrAPWk'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'APEX QR Scanner Plugin',
'Scans QR codes with the device camera and writes the decoded text into a page item.',
'',
'HOW TO USE',
'1. Create a Text Field page item (for example P10_QR_RESULT). Set Value Protected to No.',
'2. Add a region of this type.',
'3. Set the attributes:',
'   - Target Page Item: the item that receives the QR text.',
'   - Camera Facing: Rear Camera (phones) or Front Camera. A laptop webcam is used automatically if no rear camera exists.',
'   - Stop After Scan: Yes stops the camera after the first successful scan.',
'4. Optional: create a Dynamic Action on the event "QR Scanned". Read the value with this.data.value.',
'',
'REQUIREMENTS',
'- The page must be opened over HTTPS, or the browser will block the camera.',
'- The user must tap Start Camera and allow camera permission.',
'',
'SECURITY',
'A QR code is only text. Always validate the value on the server before using it for tickets, attendance, or payments.',
'',
'Free and open source (MIT License). Includes jsQR (Apache-2.0).'))
,p_version_identifier=>'1.0.0'
,p_about_url=>'https://github.com/VihenTheekshadha/apex-qr-scanner-plugin'
,p_plugin_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Author: Vihen Theekshadha',
'License: MIT. Bundles jsQR 1.4.0 (Apache-2.0) by Cosmo Wolfe.',
'Tested on: Oracle APEX 26.1.5 (Autonomous Database), desktop browser and iOS.',
'Render interface: procedure (p_plugin, p_region, p_param, p_result).',
'Files: js/jsQR.js, js/qr-scanner.js, css/qr-scanner.css.',
'Event: qr-scanned (event detail: value, item, regionId).'))
,p_files_version=>2461316155350
);
